-- Fix for: null value in column "user_id" of relation "userinfo" violates not-null constraint
-- Cause: userinfo.user_id is NOT NULL but has no default/identity generation.
--
-- Apply in Supabase SQL editor.
--
-- This makes user_id auto-generated (identity) so inserts that omit user_id work.

do $$
begin
  -- Only attempt if the table/column exists.
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'userinfo'
      and column_name = 'user_id'
  ) then
    -- Add identity generation if not already present.
    -- (If it's already identity or has a default, this may error; we swallow those cases.)
    begin
      alter table public.userinfo
        alter column user_id add generated by default as identity;
    exception
      when duplicate_object then
        null; -- already identity
      when invalid_table_definition then
        null; -- column type not compatible or already has default/identity
      when others then
        -- If the column already has a default, Postgres raises different errors depending on version.
        -- We ignore to keep this script idempotent-ish; inspect manually if needed.
        null;
    end;
  end if;
end $$;

